def solve(T_C=28, r_g_kg=23) -> dict:
    # Convert temperature to Kelvin and mixing ratio to kg/kg
    T_K = T_C + 273.15
    r_kg_kg = r_g_kg / 1000.0

    # Calculate virtual temperature in Kelvin
    # Formula: T_v = T * [1 + (0.61 * r)]
    T_v_K = T_K * (1.0 + 0.61 * r_kg_kg)

    # Convert virtual temperature back to °C
    T_v_C = T_v_K - 273.15

    return {
        "1": {"value": (T_v_C), "unit": "°C"}
    }

