def solve(T_C=24, P=106, P0=100.0, R_Cp=0.286) -> dict:
    # Convert temperature to Kelvin
    T_K = T_C + 273.15

    # Calculate potential temperature in Kelvin: theta = T * (P0 / P)^(R/C_p)
    theta_K = T_K * (P0 / P) ** R_Cp

    # Convert potential temperature back to Celsius
    theta_C = theta_K - 273.15

    return {
        "1": {"value": (theta_C), "unit": "°C"},
    }

