def solve(P=73, T_C=30, Td_C=6.411) -> dict:
    # Convert temperatures to Kelvin
    T_K = T_C + 273.15
    Td_K = Td_C + 273.15

    # Calculate LCL pressure using the provided empirical formula
    # P_LCL = P * [1 - 1.225 * (T - T_d) / T]^3.5
    P_LCL = P * (1 - 1.225 * (T_K - Td_K) / T_K)**3.5

    return {
        "1": {"value": round(P_LCL, 2), "unit": "kPa"}
    }

