def solve(H_km=4.048, vd_cm_s=0.944) -> dict:
    # Convert height of the layer from km to meters
    H_m = H_km * 1000.0

    # Convert deposition velocity from cm/s to m/s
    vd_m_s = vd_cm_s / 100.0

    # Calculate the residence time (time to deposit all SO2 assuming constant initial rate)
    # Time = Total column mass / Deposition flux = (H * C) / (vd * C) = H / vd
    t_s = H_m / vd_m_s

    # Convert time from seconds to days
    t_days = t_s / (24 * 3600)

    return {
        "1": {"value": t_days, "unit": "days"}
    }

