def solve(sigma_total=4.048, sigma_season=3.54) -> dict:
    # Total variance is the sum of variance of seasonal means and variance within seasons
    # Var_total = Var_season + Var_within
    var_total = sigma_total ** 2
    var_season = sigma_season ** 2

    # Calculate variance within seasons (variance of monthly means about seasonal means)
    var_within = var_total - var_season

    # Standard deviation within seasons
    sigma_within = math.sqrt(var_within)

    return {
        "1": {"value": sigma_within, "unit": "°C"}
    }

