def solve(rho_p=2.867, d1=0.0458, d2=0.11371, d3=0.57087, d4=0.86066):
    # rho_p in g/cm^3, diameters in micrometers
    import math

    # Physical constants / properties of air at ~standard conditions
    rho_p_SI = rho_p * 1000.0        # kg/m^3  (2.65 g/cm3 -> 2650 kg/m3)
    g = 9.81                          # m/s^2
    mu = 1.81e-5                      # Pa.s, dynamic viscosity of air at 20C
    mfp = 0.0651e-6                   # m, mean free path of air (~0.0651 um)

    diameters_um = [d1, d2, d3, d4]

    def cunningham(dp):
        # dp in meters
        Kn = 2.0 * mfp / dp
        return 1.0 + Kn * (1.257 + 0.40 * math.exp(-1.10 / Kn))

    velocities = []
    for d_um in diameters_um:
        dp = d_um * 1e-6  # m
        Cc = cunningham(dp)
        vt = (rho_p_SI * dp**2 * g * Cc) / (18.0 * mu)  # m/s
        velocities.append(vt)

    results = {}
    for i, vt in enumerate(velocities, start=1):
        results[str(i)] = {"value": vt, "unit": "m/s"}

    return results

