    Omega = 7.292115e-5  # Earth's rotation rate, s^-1
    f = 2.0 * Omega * math.sin(math.radians(lat_deg))
    amplitude = r * ug / math.sqrt(r**2 + f**2)
    return {"1": {"value": amplitude, "unit": "m s^-1"}}

