def solve(T_air=264.0, H_c=333.0, dz_mm=1.0):
    # Physical constant: thermal conductivity of dry air near 295 K (W m^-1 K^-1)
    k_air = 0.026  # W/(m*K)

    # Unit conversion: 1 mm to meters
    dz = dz_mm * 1e-3  # m

    # Fourier's law for conduction through the thin air layer:
    # H_c = k_air * (T_ground - T_air) / dz
    # Solve for ground temperature
    T_ground = T_air + H_c * dz / k_air  # K

    return {
        "1": {"value": T_ground, "unit": "K"}
    }

