def solve(fraction_frozen=0.4, aerosol_conc=1040.0, temperature_C=-16.8,
          K=0.0001, max_contact_fraction=0.05):
    import math

    # Number concentration of available contact nuclei (cm^-3)
    N = max_contact_fraction * aerosol_conc  # particles cm^-3

    # Fraction frozen follows: f = 1 - exp(-K*N*t)
    # Solve for t: t = -ln(1 - f) / (K*N)
    t = -math.log(1.0 - fraction_frozen) / (K * N)  # seconds

    return {
        "1": {"value": t, "unit": "s"}
    }

