def solve(M_O=10.0, M_F=8.0, sigma_f=2.857, sigma_o=3.725) -> dict:
    # Variances
    var_f = sigma_f ** 2
    var_o = sigma_o ** 2

    # Optimum interpolation equation
    # M_A = M_F * (sigma_o^2 / (sigma_f^2 + sigma_o^2)) + M_O * (sigma_f^2 / (sigma_f^2 + sigma_o^2))
    M_A = M_F * (var_o / (var_f + var_o)) + M_O * (var_f / (var_f + var_o))

    return {
        "1": {"value": round(M_A, 1), "unit": "m s^{-1}"}
    }

