def solve(beta_c_deg=49, n_ice=1.3135, n_air=1.0) -> dict:
    # Convert wedge angle to radians for math functions
    beta_c_rad = math.radians(beta_c_deg)

    # Calculate the minimum viewing angle using the given formula:
    # Theta_2min = 2 * arcsin[ (n_ice / n_air) * sin(beta_c / 2) ] - beta_c
    sin_term = (n_ice / n_air) * math.sin(beta_c_rad / 2.0)
    theta_2min_rad = 2.0 * math.asin(sin_term) - beta_c_rad

    # Convert the result back to degrees
    theta_2min_deg = math.degrees(theta_2min_rad)

    return {
        "1": {"value": round(theta_2min_deg, 2), "unit": "°"}
    }

