def solve(T_2_2=18, T_4_2=28, U_25_2=-4.007, U_35_2=-6.031, dX=11417) -> dict:
    # Centered difference approximation for advection on a staggered grid
    # U_avg is the velocity at grid point (3, 2)
    U_avg = (U_35_2 + U_25_2) / 2.0

    # Temperature gradient dT/dx at grid point (3, 2)
    dT_dx = (T_4_2 - T_2_2) / (2.0 * dX)

    # Warming rate in °C/s (Advection = -U * dT/dx)
    warming_rate_s = -U_avg * dT_dx

    # Convert warming rate to °C/h
    warming_rate_h = warming_rate_s * 3600.0

    return {
        "1": {"value": round(warming_rate_h, 2), "unit": "^\\circ°C h}^{-1}"}
    }

