import math

def solve(K=0.00108, latitude_deg=39):
    # Physical constants
    Omega = 7.292115e-5  # Earth's angular velocity (rad/s)

    # Coriolis parameter
    phi = math.radians(latitude_deg)
    f = 2.0 * Omega * math.sin(phi)

    # Ekman layer depth scale: D = pi * sqrt(2K/f)
    D = math.pi * math.sqrt(2.0 * K / f)

    return {
        "1": {"value": D, "unit": "m"}
    }

