def solve(p1=815, p2=757, H=7290, Z1=0) -> dict:
    import math

    # Hypsometric equation: Z2 - Z1 = H * ln(p1/p2)
    # p1/p2 can be written as 1 + x, where x = (p1 - p2) / p2
    x = (p1 - p2) / p2

    # Using the given approximation ln(1+x) ≈ x for x << 1
    Z2 = Z1 + H * x

    return {
        "1": {"value": Z2, "unit": "m"}
    }

