def solve(p_LFC=567, p_EL=207, delta_T=8.013) -> dict:
    """
    Estimate the convective available potential energy (CAPE).
    """
    # CAPE approximation: CAPE = R_d * delta_T * ln(p_LFC / p_EL)
    # delta_T is the average temperature difference (10 C difference = 10 K difference)
    R_d = 287  # physical constant (frozen, not an input)
    cape = R_d * delta_T * math.log(p_LFC / p_EL)

    return {
        "1": {"value": cape, "unit": "J kg^-1"}
    }

