def solve(theta_sfc=4.048, lapse_rate=3.54, Q_Ak=0.40066) -> dict:
    import math

    # Calculate mixed-layer depth (z_i)
    # Formula: Q_Ak = 0.5 * lapse_rate * z_i^2
    z_i = math.sqrt(2 * Q_Ak / lapse_rate)

    # Calculate mixed-layer potential temperature (theta_ML)
    # Formula: theta_ML = theta_sfc + lapse_rate * z_i
    theta_ML = theta_sfc + lapse_rate * z_i

    return {
        "1": {"value": round(z_i, 3), "unit": "km"},
        "2": {"value": round(theta_ML, 2), "unit": r"°C"}
    }

